EA(K,'ZS06','Appalti e interferenze',[LB("Laboratorio · Il coordinamento di tre appalti contemporanei","Uno stabilimento ha nello stesso mese tre appalti: manutenzione del tetto, pulizie industriali e installazione di una nuova linea.",[
  ["Tetto","impresa A, lavori in quota sopra il reparto produttivo"],["Pulizie","impresa B, uso di macchine lavapavimenti e detergenti"],["Linea","impresa C, montaggio con gru mobile e saldature"],["Produzione","attiva su due turni"]],[
  ("Individua le interferenze tra imprese e con la produzione.",7,"Caduta di materiali dal tetto sulle aree di lavoro di B, C e della produzione; incendio da saldature di C vicino ai detergenti di B e a materiali combustibili; movimentazione della gru di C nelle vie di transito; pavimenti bagnati da B nelle aree di montaggio.",["Ho individuato interferenze tra imprese","Ho considerato la produzione"]),
  ("Come organizzi DUVRI e coordinamento?",7,"DUVRI unico aggiornato con le tre imprese; cronoprogramma che separa nel tempo e nello spazio le attività incompatibili; riunione di coordinamento iniziale e settimanale; permessi di lavoro per quota e lavori a caldo; referente del committente.",["Ho previsto il DUVRI aggiornato","Ho previsto cronoprogramma e permessi"]),
  ("Come verifichi in corso d’opera?",7,"Sopralluoghi quotidiani del referente; verifica dei preposti delle imprese indicati al committente; sospensione delle attività in caso di interferenze non gestite; registro delle verifiche.",["Ho previsto sopralluoghi","Ho previsto la sospensione"])],
 "Nel laboratorio coordini tre appalti contemporanei: interferenze, DUVRI e coordinamento, verifiche in corso d’opera. Confronta ogni risposta con la soluzione di riferimento.","Art. 26 D.lgs. 81/2008")])
EA(K,'ZS07','Prevenzione incendi e emergenze: il quadro dei tre decreti',[SC("Quale decreto?","Un’impresa deve aggiornare la gestione antincendio: manutenzione degli estintori, formazione degli addetti e progettazione di un nuovo magazzino a basso rischio.",[
 ("Per manutenzione e qualificazione dei manutentori?",[["D.M. 1 settembre 2021, con le modifiche recenti",True,"Corretto."],["D.M. 2 settembre 2021",False,"Riguarda la gestione dell’emergenza."],["D.M. 3 settembre 2021",False,"Riguarda la progettazione."]]),
 ("Per la formazione degli addetti e il piano di emergenza?",[["D.M. 2 settembre 2021",True,"Corretto."],["D.M. 1 settembre 2021",False,"Riguarda i controlli."],["D.P.R. 151/2011",False,"Riguarda le attività soggette."]]),
 ("Per i criteri di progettazione del magazzino a basso rischio?",[["D.M. 3 settembre 2021",True,"Corretto: criteri generali per i luoghi di lavoro."],["D.M. 2 settembre 2021",False,"Riguarda l’emergenza."],["Nessun decreto",False,"Il decreto esiste."]])],
 "Tre decreti, tre materie: controlli e manutenzione, gestione dell’emergenza e formazione, criteri di progettazione e gestione della sicurezza antincendio.","Tre esigenze antincendio. Collegale al decreto giusto.","D.M. 1, 2 e 3 settembre 2021")])
EA(K,'ZS08','Esempio applicativo: il carico di incendio specifico',[LB("Laboratorio · Il carico di incendio di un magazzino","Calcoli il carico di incendio specifico di un magazzino di imballaggi.",[
  ["Superficie","400 m²"],["Materiali","4.000 kg di legno (H ≈ 17,5 MJ/kg); 1.000 kg di polietilene (H ≈ 44 MJ/kg)"],["Ipotesi","mi = 1 e ψi = 1, stima cautelativa"]],[
  ("Calcola il carico di incendio specifico qf.",7,"Q = 4.000 × 17,5 + 1.000 × 44 = 70.000 + 44.000 = 114.000 MJ. qf = 114.000 / 400 = 285 MJ/m².",["Ho calcolato Q","Ho calcolato 285 MJ/m²"]),
  ("Come si passa al valore di progetto?",6,"Il carico di progetto si ottiene moltiplicando qf per fattori che tengono conto del rischio di incendio legato a superficie e attività e delle misure di protezione presenti, secondo il Codice di prevenzione incendi.",["Ho spiegato i fattori correttivi","Ho citato il Codice"]),
  ("Come puoi ridurre il carico di incendio?",7,"Ridurre le scorte di imballaggi in plastica; separare i materiali in compartimenti; usare materiali meno combustibili; installare protezioni attive che migliorano i fattori di progetto.",["Ho proposto riduzione e separazione","Ho considerato le protezioni attive"])],
 "Nel laboratorio calcoli il carico di incendio specifico di un magazzino di imballaggi, spieghi il passaggio al valore di progetto e proponi come ridurlo. Confronta ogni risposta con la soluzione di riferimento.","D.M. 3 agosto 2015, Codice di prevenzione incendi")])
EA(K,'ZS09','Il codice di prevenzione incendi',[LB("Laboratorio · La strategia antincendio con il Codice","Imposti la strategia antincendio di un’attività con il Codice di prevenzione incendi.",[
  ["Attività","laboratorio artigianale di falegnameria con 15 addetti e un piccolo deposito di vernici"],["Edificio","un piano, 800 m²"]],[
  ("Come determini i profili di rischio?",6,"Rvita in base alla tipologia degli occupanti, che sono svegli e hanno familiarità con l’edificio, e alla velocità di crescita dell’incendio; Rbeni in base al valore e al carattere dell’edificio; Rambiente in base agli effetti sull’ambiente.",["Ho descritto Rvita","Ho descritto Rbeni e Rambiente"]),
  ("Quali misure della strategia ritieni più rilevanti?",8,"S.2 resistenza al fuoco e S.3 compartimentazione per il deposito di vernici; S.4 esodo; S.5 gestione della sicurezza antincendio; S.6 controllo dell’incendio con estintori adeguati; S.7 rivelazione e allarme; S.8 controllo di fumi e calore; S.10 sicurezza degli impianti.",["Ho selezionato le misure","Ho collegato il deposito di vernici"],None,120),
  ("Come scegli i livelli di prestazione e le soluzioni?",6,"Per ogni misura si attribuisce il livello di prestazione secondo i criteri del Codice e si sceglie una soluzione conforme, alternativa o in deroga, documentando le scelte.",["Ho descritto livelli e soluzioni","Ho previsto la documentazione"])],
 "Nel laboratorio imposti la strategia antincendio di una falegnameria con il Codice di prevenzione incendi: profili di rischio, misure rilevanti, livelli di prestazione e soluzioni. Confronta ogni risposta con la soluzione di riferimento.","D.M. 3 agosto 2015 e s.m.i.")])
EA(K,'ZS10','Atmosfere esplosive: classificazione delle zone e apparecchiature',[LB("Laboratorio · Classificare le zone e scegliere le apparecchiature","Classifichi le zone di un locale di miscelazione di vernici a solvente e di un silo di farina.",[
  ["Locale vernici","fusti aperti durante la miscelazione; ventilazione naturale"],["Silo","interno del silo e zona del filtro; scarico con manichetta"],["Apparecchiature","motori e illuminazione da scegliere"]],[
  ("Classifica le zone principali.",7,"Interno dei fusti aperti: zona 0. Intorno alle bocche durante la miscelazione: zona 1. Resto del locale con perdite improbabili: zona 2, da verificare con il grado di ventilazione. Interno del silo: zona 20; intorno allo scarico: zona 21 o 22 secondo frequenza e durata.",["Ho classificato le zone per i vapori","Ho classificato le zone per le polveri"]),
  ("Quali categorie di apparecchiature servono?",6,"Categoria 1 per zone 0 e 20; categoria 2 per zone 1 e 21; categoria 3 per zone 2 e 22, con il gruppo e la classe di temperatura adatti alla sostanza.",["Ho associato le categorie alle zone","Ho considerato classe di temperatura"]),
  ("Quali documenti e misure organizzative completano la protezione?",7,"Documento sulla protezione contro le esplosioni; segnaletica delle zone; permessi di lavoro per lavori a caldo; formazione; abbigliamento e attrezzi idonei; verifiche degli impianti elettrici nelle zone classificate.",["Ho citato il documento","Ho previsto permessi e verifiche"])],
 "Nel laboratorio classifichi le zone di un locale vernici e di un silo di farina e scegli le categorie di apparecchiature, completando con documenti e misure organizzative. Confronta ogni risposta con la soluzione di riferimento.","Titolo XI D.lgs. 81/2008 · CEI EN IEC 60079-10-1 e 60079-10-2 · D.lgs. 85/2016")])
EA(K,'ZS11','Le attività soggette: il D.P.R. 151/2011',[SC("La nuova attività soggetta","Un’impresa amplia il deposito di materiali combustibili oltre la soglia che lo rende attività soggetta ai controlli dei Vigili del fuoco.",[
 ("Che cosa deve fare prima di esercitare l’attività ampliata?",[["Verificare la categoria nell’Allegato I e seguire il procedimento previsto, con SCIA prima dell’avvio",True,"Corretto."],["Nulla, basta l’assicurazione",False,"L’attività soggetta richiede il procedimento."],["Aspettare il controllo dei Vigili del fuoco",False,"L’iniziativa è dell’impresa."]]),
 ("Se l’attività è in categoria B o C, che cosa serve prima?",[["La valutazione del progetto da parte del Comando dei Vigili del fuoco",True,"Corretto."],["Nulla",False,"Serve la valutazione del progetto."],["Solo un’autocertificazione",False,"Non basta."]]),
 ("Ogni quanto si rinnova la conformità antincendio?",[["Con l’attestazione periodica di rinnovo nei tempi previsti, di norma ogni cinque anni",True,"Corretto."],["Mai",False,"Il rinnovo è periodico."],["Ogni anno",False,"Non è la regola generale."]])],
 "Le attività soggette seguono un procedimento graduato per categoria: valutazione del progetto per B e C, SCIA prima dell’avvio e rinnovo periodico.","Un deposito diventa attività soggetta. Imposta il procedimento.","D.P.R. 151/2011")])
EA(K,'ZS12','Formazione: le regole operative dell\'Accordo 2025',[CL("Regola rispettata o no?","Seleziona una situazione d’aula, poi la colonna.",["Conforme all’Accordo 2025","Non conforme"],[
 ["Corso con 28 partecipanti",0,"Il massimo è 30."],["Prova pratica con un istruttore ogni 10 allievi",1,"Il rapporto nelle attività pratiche è 1:6."],
 ["Partecipante con frequenza dell’85%",1,"Serve almeno il 90%."],["Videoconferenza seguita da smartphone",1,"Non ammessa."],
 ["Test finale di 30 domande con soglia del 70%",0,"Conforme per un corso base."],["Fascicolo conservato per 10 anni",0,"Conforme."]],
 "Sei situazioni d’aula. Distingui quelle conformi alle regole operative dell’Accordo 2025.","Accordo Stato-Regioni 17 aprile 2025")])
EA(K,'ZS13','Analisi dei fabbisogni formativi',[LB("Laboratorio · L’analisi dei fabbisogni formativi","Analizzi i fabbisogni formativi di un reparto di produzione dopo un anno con molti quasi incidenti.",[
  ["Dati","20 quasi incidenti, 12 legati a carrelli e pedoni; 3 infortuni da taglio con coltelli"],["Organico","25 lavoratori, di cui 8 neoassunti e 6 di lingua straniera"],["Osservazioni dei preposti","uso discontinuo dei guanti antitaglio; percorsi pedonali non rispettati"]],[
  ("Analizza i fabbisogni a livello organizzativo, di ruolo e individuale.",8,"Organizzativo: separare pedoni e carrelli è anzitutto un problema di layout, non solo di formazione. Ruolo: carrellisti, addetti al taglio e preposti hanno bisogni diversi. Individuale: neoassunti e lavoratori stranieri richiedono formazione iniziale e verifica della lingua.",["Ho distinto i tre livelli","Ho separato problemi organizzativi e formativi"],None,120),
  ("Quali interventi formativi proponi?",7,"Addestramento pratico per i carrellisti sulla circolazione; addestramento all’uso dei guanti antitaglio e dei coltelli di sicurezza; percorsi per i neoassunti con verifica della comprensione; formazione dei preposti sull’intervento e sul riconoscimento dei comportamenti.",["Ho proposto interventi per ruolo","Ho incluso i preposti"]),
  ("Quali interventi non formativi servono insieme?",6,"Percorsi pedonali protetti; coltelli di sicurezza; guanti più confortevoli scelti con gli addetti; segnaletica; vigilanza dei preposti.",["Ho proposto interventi tecnici e organizzativi"])],
 "Nel laboratorio analizzi i fabbisogni formativi di un reparto dopo molti quasi incidenti, distinguendo i livelli e separando ciò che la formazione può risolvere da ciò che richiede altri interventi. Confronta ogni risposta con la soluzione di riferimento.","Art. 37 D.lgs. 81/2008 · Accordo 17 aprile 2025")])
EA(K,'ZS14','Costruire un buon test di verifica',[LB("Laboratorio · Riscrivere domande di verifica","Correggi tre domande di un test di verifica e scrivine una nuova.",[
  ["Domanda 1","«Non è vero che il preposto non debba vigilare?» con risposte sì/no"],["Domanda 2","«Quale DPI si usa?» con risposte: A) guanti B) tutte le precedenti C) nessuna delle precedenti"],["Domanda 3","«L’art. 37 è al comma 13?» con risposte vero/falso"]],[
  ("Riscrivi la domanda 1 eliminando i difetti.",5,"«Quale compito spetta al preposto quando un lavoratore non usa i DPI previsti?» con distrattori plausibili, ad esempio annotarlo a fine turno, chiedere al collega di intervenire, interrompere l’attività se l’inosservanza persiste.",["Ho eliminato la doppia negazione","Ho reso la domanda applicativa"]),
  ("Riscrivi la domanda 2.",5,"Domanda contestualizzata: «Per la molatura di pezzi con proiezione di schegge quale DPI per gli occhi è adeguato?» con distrattori omogenei, senza «tutte» o «nessuna delle precedenti».",["Ho contestualizzato la domanda","Ho eliminato le opzioni vietate"]),
  ("Scrivi una nuova domanda applicativa con calcolo.",8,"«Un addetto è esposto a 92 dB(A) per 2 ore e a 85 dB(A) per 4 ore, il resto in silenzio. Il suo LEX,8h è circa:» A) 85 dB(A) B) 87,5 dB(A) C) 92 dB(A) D) 89 dB(A). Corretta B.",["Ho scritto una domanda di calcolo","Ho previsto distrattori plausibili"],None,80)],
 "Nel laboratorio correggi tre domande di un test di verifica e ne scrivi una nuova applicativa, seguendo le regole per un buon test. Confronta ogni risposta con la soluzione di riferimento.","Accordo 17 aprile 2025, punto 6")])
EA(K,'ZS15','Formazione a distanza: e-learning e videoconferenza sincrona',[LB("Laboratorio · Scegliere la modalità di erogazione","Scegli la modalità di erogazione per cinque corsi di un piano formativo.",[
  ["Corsi","formazione generale dei lavoratori; formazione specifica rischio alto; corso preposti; aggiornamento RSPP; corso per addetti al carrello elevatore"]],[
  ("Indica per ciascun corso le modalità ammesse.",8,"Generale: e-learning ammesso, anche videoconferenza sincrona o presenza. Specifica rischio alto: non in e-learning; presenza o videoconferenza sincrona per la teoria. Preposti: presenza o videoconferenza sincrona, non e-learning. Aggiornamento RSPP: e-learning ammesso secondo l’Accordo. Carrello elevatore: pratica in presenza; teoria secondo le regole dell’Accordo.",["Ho rispettato i divieti di e-learning","Ho previsto la pratica in presenza"],None,120),
  ("Quali requisiti deve avere la piattaforma e-learning?",6,"Tracciamento di tempi, accessi e avanzamento; tutor di contenuto; test intermedi e finale; conservazione dei dati; contenuti non saltabili; identificazione del partecipante.",["Ho elencato tracciamento e tutor","Ho previsto test e conservazione"]),
  ("Quali regole per la videoconferenza sincrona?",6,"Un dispositivo per partecipante, niente smartphone, webcam attiva, tutor, registro delle presenze e verifica dell’identità.",["Ho elencato le regole"])],
 "Nel laboratorio scegli la modalità di erogazione per cinque corsi e definisci i requisiti di e-learning e videoconferenza sincrona. Confronta ogni risposta con la soluzione di riferimento.","Accordo Stato-Regioni 17 aprile 2025")])
EA(K,'ZS16','Il docente formatore: i requisiti del D.I. 6 marzo 2013',[SC("Il nuovo docente","Un ingegnere con dieci anni di esperienza come RSPP, senza esperienza di docenza, vuole tenere corsi per lavoratori.",[
 ("Che cosa verifichi?",[["Il prerequisito del diploma e il soddisfacimento di almeno uno dei criteri del decreto per l’area tematica",True,"Corretto."],["Solo la laurea",False,"Servono i criteri del decreto."],["Nulla, l’esperienza basta",False,"Va verificata la combinazione richiesta."]]),
 ("Quale percorso può completare i requisiti?",[["Un percorso formativo per formatori abbinato all’esperienza professionale nell’area, secondo i criteri",True,"Corretto."],["Un solo webinar",False,"Non basta."],["Nessuno",False,"I criteri prevedono percorsi."]]),
 ("Come mantiene la qualificazione?",[["Con l’aggiornamento periodico previsto per i formatori",True,"Corretto."],["Non serve aggiornarsi",False,"L’aggiornamento è richiesto."],["Facendo un corso ogni dieci anni",False,"La periodicità è più frequente."]])],
 "Il docente formatore deve avere il prerequisito e almeno uno dei criteri del decreto, e mantenere la qualificazione con l’aggiornamento.","Un esperto vuole diventare docente. Verifica i requisiti.","D.I. 6 marzo 2013")])
EA(K,'ZS17','Comunicazione del rischio',[LB("Laboratorio · Comunicare un rischio ai lavoratori","Prepari la comunicazione dei risultati delle misure di silice in un laboratorio di lapidei.",[
  ["Risultati","esposizione al taglio pari a circa la metà del valore limite; sotto il limite ma non trascurabile"],["Destinatari","12 lavoratori, alcuni preoccupati, altri indifferenti"],["Misure decise","taglio ad acqua su tutte le macchine, pulizia a umido, sorveglianza sanitaria"]],[
  ("Scrivi il messaggio chiave in linguaggio semplice.",6,"«Le misure mostrano che respiriamo polvere di silice in quantità inferiori al limite, ma non trascurabili. La silice può danneggiare i polmoni nel tempo. Per questo introduciamo il taglio ad acqua e la pulizia a umido.»",["Ho usato linguaggio semplice","Ho evitato di minimizzare o allarmare"]),
  ("Come presenti i dati?",6,"Con un grafico semplice che confronta i valori misurati con il limite e con l’obiettivo; spiegazione di che cosa significa «sotto il limite»; risposta alle domande.",["Ho previsto una visualizzazione semplice","Ho previsto spazio per le domande"]),
  ("Come rendi coerenti messaggi e comportamenti?",6,"La direzione partecipa all’incontro; le misure partono subito; il preposto verifica l’uso del taglio ad acqua; i lavoratori ricevono il riscontro sui risultati dopo gli interventi.",["Ho previsto coerenza della direzione","Ho previsto il riscontro"])],
 "Nel laboratorio prepari la comunicazione dei risultati delle misure di silice: messaggio chiave, presentazione dei dati e coerenza tra messaggi e comportamenti. Confronta ogni risposta con la soluzione di riferimento.","Art. 36 D.lgs. 81/2008")])
EA(K,'ZS18','La percezione del rischio',[LB("Laboratorio · Contrastare la normalizzazione della devianza","In un magazzino si usano le forche del carrello per sollevare un collega fino agli scaffali alti: «si è sempre fatto, mai successo niente».",[
  ["Prassi","sollevamento di persone su un pallet sulle forche"],["Percezione","rischio considerato basso per familiarità"],["Alternative disponibili","piattaforma di lavoro elevabile in un altro reparto"]],[
  ("Quali meccanismi di percezione spiegano la prassi?",6,"Normalizzazione della devianza: lo scostamento che non ha prodotto danni diventa normale; familiarità con il compito; bias di ottimismo; percezione di controllo.",["Ho riconosciuto la normalizzazione della devianza","Ho citato almeno due bias"]),
  ("Come intervieni sulla percezione?",7,"Racconto di casi reali di cadute da forche; spiegazione del meccanismo di caduta e delle conseguenze; coinvolgimento dei lavoratori nella ricerca di soluzioni; esempio coerente dei responsabili.",["Ho usato casi concreti","Ho coinvolto i lavoratori"]),
  ("Quali misure concrete accompagnano la comunicazione?",6,"Divieto chiaro e vigilanza dei preposti; piattaforma elevabile disponibile dove serve; procedura per i prelievi in quota; riconoscimento dei comportamenti corretti.",["Ho previsto divieto e alternativa","Ho previsto vigilanza"])],
 "Nel laboratorio affronti una prassi pericolosa normalizzata in un magazzino: meccanismi di percezione, intervento sulla percezione e misure concrete. Confronta ogni risposta con la soluzione di riferimento.","Art. 71 D.lgs. 81/2008 · letteratura sulla percezione del rischio")])
EA(K,'ZS19','Esercitazione 5 · Decreto e contenuto',[AP("La formazione e la comunicazione nella tua attività di RSPP","Verifica la qualità della formazione e della comunicazione che curi.",["Analisi dei fabbisogni documentata","Test con domande applicative","Verifica dell’efficacia a 30-90 giorni","Regole dell’Accordo 2025 applicate","Brevi riunioni di reparto","Comunicazione dei risultati delle misure ai lavoratori"],"L’aspetto che migliorerai nel prossimo corso","Es.: domande di verifica basate su casi reali",
  "Verifica la qualità della formazione e della comunicazione che curi e indica che cosa migliorerai nel prossimo corso.",3)])
